SELECT



ORDER BY


        ${filter.orderBy}


        budget_pls.id DESC


LIMIT #{filter.page}, #{filter.rowsPerPage}

SELECT IFNULL(SUM(IFNULL(gld.credit, 0)) - SUM(IFNULL(gld.debit, 0)), 0)
FROM general_ledgers AS gl
     INNER JOIN general_ledger_details AS gld ON gl.id=gld.general_ledger_id
WHERE gld.chart_account_id = #{chartAccountId}
    AND gl.is_active=1
    AND MONTH(gl.date) = #{month} AND YEAR(gl.date) = #{year}

SELECT COUNT(id)
FROM budget_pls
WHERE is_active = 1 AND name = #{name}
 AND id != #{id}

mapper.update:
UPDATE budget_pls SET
                      is_active = 2,
                      modified = NOW(),
                      modified_by = #{userId}
WHERE id = #{id};
